const exams=packs.map(({company,n,mcq,written})=>{
  const lines=mcq.trim().split('\n').filter(Boolean);
  if(lines.length!==40||written.length!==10)throw new Error(`${company}-${n}: ${lines.length} QCM, ${written.length} courtes`);
  const counters=Object.fromEntries(sections.map(s=>[s,0]));
  const positions=Array.from({length:40},(_,i)=>i%4);let seed=n+(company==='RVA'?997:43);
  for(let i=positions.length-1;i>0;i--){seed=(Math.imul(seed,1664525)+1013904223)>>>0;const j=seed%(i+1);[positions[i],positions[j]]=[positions[j],positions[i]];}
  const questions=lines.map((line,i)=>{
    const [prompt,correct,...distractors]=line.split('|');
    if(distractors.length!==3)throw new Error(line);
    let cursor=0,section;
    for(let j=0;j<sections.length;j++){cursor+=mcqCounts[j];if(i<cursor){section=sections[j];break;}}
    const answer=positions[i],choices=[correct,...distractors];
    while(choices.indexOf(correct)!==answer)choices.push(choices.shift());
    return {id:`${company.toLowerCase()}${n}-${section}-M${String(++counters[section]).padStart(2,'0')}`,section,type:'mcq',prompt,choices,answer,
      explanation:`${correct}. C’est le critère déterminant ici ; les autres propositions confondent les responsabilités, négligent une contrainte ou utilisent une mesure insuffisante pour le cas présenté.`,
      commentRequired:[10,20,28,37].includes(i),sources:sources[company],lastVerified:'2026-11-05'};
  });
  const counts={};
  for(const [section,prompt,modelAnswer,...essentials] of written){
    counts[section]=(counts[section]||0)+1;
    questions.push({id:`${company.toLowerCase()}${n}-${section}-S${counts[section]}`,section,type:'short',prompt,instruction:'Répondez en distinguant le rôle de supervision du PCA et l’exécution par la DG. Justifiez les priorités et les calculs utiles.',modelAnswer,essentials,minWords:60,maxWords:100,commentRequired:false,sources:sources[company],lastVerified:'2026-11-05'});
  }
  for(let i=0;i<sections.length;i++)if(counts[sections[i]]!==shortCounts[i])throw new Error('Répartition écrite invalide');
  return {id:`${company.toLowerCase()}-${n}`,company,title:`${company} — Simulation technique ${n}`,durationMinutes:60,
    notice:'Cas de gestion et chiffres hypothétiques, distincts des données réelles. Répartition pédagogique : 40 QCM à 1 point et 10 réponses courtes à 6 points. Sources institutionnelles pour les missions ; raisonnements de gestion proposés pour la simulation.',questions};
});
const reviewPath=new URL('../data/reviewed-technical-options.json',import.meta.url);
if(fs.existsSync(reviewPath))applyReviewedOptions(exams,JSON.parse(fs.readFileSync(reviewPath,'utf8')));
